/**
 * Deletes a product permanently
 */
export async function deleteProductAction(id: string) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    await db.delete(products).where(eq(products.id, id));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true };
  } catch (error: any) {
    console.error("deleteProductAction error:", error);
    return { success: false, error: error?.message || "Failed to delete product" };
  }
}

/**
 * Toggles product availability between in-stock and out-of-stock
 */
export async function toggleProductAvailability(
  id: string,
  currentStatus: boolean
) {
  try {
    const session = await auth();
    if (!session) {
      return { success: false, error: "Unauthorized" };
    }

    const newStatus = !currentStatus;

    await db
      .update(products)
      .set({ isAvailable: newStatus })
      .where(eq(products.id, id));

    revalidatePath("/admin/products");
    revalidatePath("/api/products");

    return { success: true, isAvailable: newStatus };
  } catch (error: any) {
    console.error("toggleProductAvailability error:", error);
    return {
      success: false,
      error: error?.message || "Failed to toggle product availability",
    };
  }
}

